import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
} from '@angular/core';
import { QDividerOrientation } from './types/divider-orientation.type';
import { QDividerStyle } from './types/divider-style.type';
import { QDividerVariant } from './types/divider-variant.type';

@Component({
  selector: 'q-divider',
  template: '',
  styleUrls: ['./divider.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QDividerComponent {
  @Input() type: QDividerVariant = 'normal';
  @Input() style: QDividerStyle = 'line';
  @Input() orientation: QDividerOrientation = 'horizontal';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-divider';

  @HostBinding('attr.role') _role = 'separator';
  @HostBinding('attr.aria-orientation') get ariaOrientation(): QDividerOrientation {
    return this.orientation;
  }
  @HostBinding('class') get hostClasses(): string {
    return [
      'q-divider',
      `q-divider-${this.type}`,
      `q-divider-${this.style}`,
      `q-divider-${this.orientation}`,
    ].join(' ');
  }
}
